    private function seedOtherInstitution(Institution $yugu, $categoryMap, string $name, string $city, string $type, array $programs): void
    {
        $institution = Institution::create([
            'name' => $name,
            'city' => $city,
            'type' => $type,
        ]);

        foreach ($programs as $data) {
            $program = Program::create([
                'institution_id' => $institution->id,
                'school_id'      => null,
                'code'           => $data['code'],
                'name'           => $data['name'],
                'level'          => $data['level'] ?? 'СПО',
                'study_form'     => $data['form'] ?? 'очная',
            ]);
            $program->categories()->attach(
                collect($data['spheres'])->map(fn($s) => $categoryMap[$s])->filter()
            );
        }
    }
